import{_ as i,l as t,o as e,c as l,v as o,p as s,x as r,d as E,i as d,S as B}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"美元融资与互换线","description":"","frontmatter":{"title":"美元融资与互换线","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/dollar-swap-lines.md","filePath":"econ/dollar-swap-lines.md","lastUpdated":1789023840000}'),p={name:"econ/dollar-swap-lines.md"};function c(h,a,A,_,u,m){const n=t("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="美元融资与互换线" tabindex="-1">美元融资与互换线 <a class="header-anchor" href="#美元融资与互换线" aria-label="Permalink to &quot;美元融资与互换线&quot;">​</a></h1><div class="epigraph"><p>全球银行用短美元批发支撑美元资产；私人美元市场一干，本国央行印不出美元。互换线让美联储把美元流动性借给同行，是国际最后贷款人的制度形式。</p><footer>—— McGuire and von Peter, BIS；Bahaj and Reis 互换线；Goldberg, Kennedy and Miu</footer></div><p><a href="/econ/eurozone-crisis">上一课</a>写欧元同盟内的主权停止。本课——也是本课程国际金融续的收束——把危机换成全球美元融资。主干开放宏观接到三角与原罪；本课补：即使没有钉住，美元批发一停，浮动货币区的银行仍会缺美元。后课若再续，默认已经读完：官方美元流动性是全球金融周期的闸，不是限价簿上的报价技术。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>非美银行持有大量美元资产（贷款、证券），负债却是短美元（批发、外汇掉期）。国内央行最后贷款人只能提供本币。2008、2020：私人美元融资市场冻结，CIP 偏离飙升（量化栏对象），实体是美元短缺。美联储与主要央行的互换线：对方央行按约定汇率换入美元，再贷给本国银行，美联储持有外汇作为抵押。缺口不是再讲原罪企业债，而是：国际最后贷款人必须是美元的发行者，三角与 OCA 管不到这条批发腿。</p><p><span class="marginnote">Shin 的全球银行杠杆、Rey 的全球金融周期：美元风险偏好驱动跨境信贷。互换线是压力时的官方替代批发市场。Baba–Packer 写危机中的美元短缺。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>描述链条：资产美元化 + 负债批发化 ⇒ 期限与币种双错配。压力：对手方风险使批发停，掉期变成贵的合成美元（CIP 基差）。互换线把官方美元注入，压基差、避免火线出售美元资产。经验：Bahaj–Reis 显示互换利率与拍卖如何成为边际。本课不报基点时间序列，不写交易员执行。报价层见 <code>/quant/irp</code>。</p>',8)),(e(),s(B,null,{default:r(()=>[d(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20BAL%5B%22%E9%9D%9E%E7%BE%8E%E9%93%B6%E8%A1%8C%3A%20%E7%BE%8E%E5%85%83%E8%B5%84%E4%BA%A7%20%2F%20%E7%9F%AD%E7%BE%8E%E5%85%83%E5%80%BA%22%5D%20--%3E%20DRY%5B%22%E6%89%B9%E5%8F%91%E5%B9%B2%E6%B6%B8%22%5D%0A%20%20DRY%20--%3E%20CIP%5B%22%E5%90%88%E6%88%90%E7%BE%8E%E5%85%83%E5%8F%98%E8%B4%B5%22%5D%0A%20%20FED%5B%22%E7%BE%8E%E8%81%94%E5%82%A8%E4%BA%92%E6%8D%A2%E7%BA%BF%22%5D%20--%3E%20CB%5B%22%E5%A4%96%E5%9B%BD%E5%A4%AE%E8%A1%8C%22%5D%0A%20%20CB%20--%3E%20BANK%5B%22%E8%B4%B7%E7%BB%99%E6%9C%AC%E5%9B%BD%E9%93%B6%E8%A1%8C%22%5D%0A%20%20BANK%20--%3E%20THAW%5B%22%E9%81%BF%E5%85%8D%E7%81%AB%E7%BA%BF%E5%8D%96%E8%B5%84%E4%BA%A7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与储备：自有美元储备是自我保险，规模往往不够银行体系；互换是弹性的中央保险，但有对象国资格（并非全球公共品均匀供给）。与 SWF：久期相反，危机要的是现金美元不是股权组合。与欧债：OMT 是欧元名义锚，互换线是美元锚，两套地板。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是国际最后贷款人。Bagehot 在国内是对本国银行放贷；全球美元体系里，最终流动性在美联储。互换线是央行之间的 Bagehot，避免外国央行「印美元」。这改写三角叙事：浮动 + 独立货币仍可能在美元批发上不独立。原罪是新兴的币种；本课是发达银行业的美元批发——分层，不要合成一句。</p><p>欧元区 2011–12：主权回路之外，欧洲银行的美元腿同样要互换。2008 是抵押品与对手方；2020 是基金赎回与商业票据。装置相同，冲击不同。资格政治：谁能进入永久互换，谁只能临时，决定全球安全网的几何。</p><p><span class="marginnote">Cetorelli–Goldberg：全球银行在压力时重新分配内部美元。Bruno–Shin 把跨境信贷写成杠杆周期。本课要的是官方地板，不重写银行微观。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不提供如何从互换线套利的任何步骤。不重写 <code>/quant/irp</code> 的基差回归。课程在此收束开放宏观续：贸易理论从李嘉图走到任务与增长，金融从 Lucas 走到美元最后贷款人。不要把互换线写成已经替代储备需求；对无资格国家，怕浮动与储备仍在。不要进限价簿。下一课程<a href="/econ/scp-neio">产业组织</a>从 SCP / NEIO 起，不再写美元批发。</p><p>后课默认：全球银行的美元批发可以在浮动下仍制造美元荒；互换线是发行者提供的国际 LOLR。CIP 压力是价格症状。欧元主权危机与美元短缺可以同时发生、机制不同。货物比较优势与资本流之谜，到此都已接到制度闸。产业组织不再默认你还停在开放宏观。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>非美银行的美元资产靠短美元批发；本国央行印不出美元。</li><li>互换线是美联储对同行的国际最后贷款人。</li><li>浮动不取消美元批发依赖；与原罪分层。</li><li>储备是自我保险，互换是弹性中央保险，资格不均。</li><li>出处：McGuire and von Peter（BIS）；Bahaj and Reis；Goldberg, Kennedy and Miu；Shin；Rey。</li></ul>',10))])}const C=i(p,[["render",c]]);export{D as __pageData,C as default};
